#!/bin/bash
# build.sh - build dispatcher of the target [MODULE_NAME] (run by the BuildEngine inside the target image)
# Generated by LLM Cross-Compiler Framework (module wizard / Ditto) from targets/_template; same conventions as
# targets/Rockchip/modules/build.sh.
#
# Inputs (environment, set by BuildEngine):
#   MODEL_SOURCE   local HF model directory inside the container (staged by the host)
#   TARGET_FORMAT  gguf                                       (default: gguf)
#   TARGET_BOARD   board id from target.yml                   (optional)
#   QUANTIZATION   e.g. Q4_K_M, IQ4_XS, Q8_0, F16
#   JOB_TYPE       build | imatrix
#   USE_IMATRIX / IMATRIX_PATH, DATASET_PATH, MODEL_NAME, MODEL_TASK (optional)
# Outputs go to $BUILD_CACHE_DIR/output (mounted from the host). Large intermediates go to the work folder,
# never to /tmp (a small tmpfs in the build sandbox).
#
# The quantization block of the module definition becomes branches of the `case "$QUANT_TYPE"` below. A branch
# may call `build_gguf <TYPE>` (convert, quantize, clean up) or `convert_to_gguf <outtype> <file>`; every other
# type goes through build_gguf, which refuses types llama-quantize does not know. Nothing is ever copied through
# unchanged.

set -euo pipefail

WORK_DIR="${BUILD_CACHE_DIR:-/build-cache}"
OUTPUT_DIR="${WORK_DIR}/output"
IMATRIX_DIR="${WORK_DIR}/imatrix"
# Large intermediates (F16 GGUF) go to the mounted work folder; the image filesystem may be read-only.
SCRATCH_DIR="${BUILD_SCRATCH_DIR:-$WORK_DIR}"
mkdir -p "$SCRATCH_DIR"

FORMAT="$(echo "${TARGET_FORMAT:-gguf}" | tr '[:upper:]' '[:lower:]')"
BOARD="$(echo "${TARGET_BOARD:-}" | tr '[:upper:]' '[:lower:]')"
JOB_TYPE="${JOB_TYPE:-build}"
MODEL_SOURCE="${MODEL_SOURCE:-}"
MODEL_NAME="${MODEL_NAME:-$(basename "${MODEL_SOURCE%/}")}"

LLAMA_BASE="${LLAMA_CPP_PATH:-/usr/src/llama.cpp}"
CONVERT_SCRIPT="$LLAMA_BASE/convert_hf_to_gguf.py"
QUANTIZE_BIN="$LLAMA_BASE/build/bin/llama-quantize"
IMATRIX_BIN="$LLAMA_BASE/build/bin/llama-imatrix"

die() { echo "ERROR: $*" >&2; exit 1; }

# --- GGUF helpers ------------------------------------------------------------

# Output types convert_hf_to_gguf.py writes directly.
GGUF_CONVERT_TYPES=" f32 f16 bf16 q8_0 auto "
# Types accepted by llama-quantize (llama.cpp v0.6.0).
GGUF_QUANT_TYPES=" Q4_0 Q4_1 Q5_0 Q5_1 Q8_0 Q2_K Q2_K_S Q3_K_S Q3_K_M Q3_K_L Q4_K_S Q4_K_M Q5_K_S Q5_K_M Q6_K \
IQ1_S IQ1_M IQ2_XXS IQ2_XS IQ2_S IQ2_M IQ3_XXS IQ3_XS IQ3_S IQ3_M IQ4_NL IQ4_XS TQ1_0 TQ2_0 MXFP4_MOE "
# Very low-bit i-quants are unusable without an importance matrix; other i-quants lose quality without one.
GGUF_NEEDS_IMATRIX=" IQ1_S IQ1_M IQ2_XXS IQ2_XS IQ2_S "
GGUF_WANTS_IMATRIX=" IQ2_M IQ3_XXS IQ3_XS IQ3_S IQ3_M IQ4_NL IQ4_XS "

normalize_gguf_type() {
    local q
    q="$(echo "$1" | tr '[:lower:]' '[:upper:]')"
    case "$q" in
        ""|F16|FP16) echo "F16" ;;
        BF16) echo "BF16" ;;
        F32|FP32) echo "F32" ;;
        INT8|Q8) echo "Q8_0" ;;
        INT4|Q4) echo "Q4_K_M" ;;
        Q5) echo "Q5_K_M" ;;
        *) echo "$q" ;;
    esac
}

QUANT_TYPE="$(normalize_gguf_type "${QUANTIZATION:-}")"
QUANT="$QUANT_TYPE"

convert_to_gguf() {
    local outtype="$1" outfile="$2"
    [ -f "$CONVERT_SCRIPT" ] || die "llama.cpp converter not found at $CONVERT_SCRIPT (the image must build llama.cpp)."
    echo ">> Converting HF -> GGUF ($outtype)..."
    python3 "$CONVERT_SCRIPT" "$MODEL_SOURCE" --outfile "$outfile" --outtype "$outtype"
}

build_gguf() {
    local q q_lower f16_file out_file
    q="$(normalize_gguf_type "${1:-$QUANT_TYPE}")"
    q_lower="$(echo "$q" | tr '[:upper:]' '[:lower:]')"

    if [[ "$GGUF_CONVERT_TYPES" == *" $q_lower "* ]]; then
        convert_to_gguf "$q_lower" "$OUTPUT_DIR/${MODEL_NAME}-${q}.gguf"
        return
    fi
    [[ "$GGUF_QUANT_TYPES" == *" $q "* ]] || die "Unsupported GGUF quantization '$q'. Supported: F16 BF16 F32 Q8_0 and$GGUF_QUANT_TYPES"
    [ -x "$QUANTIZE_BIN" ] || die "llama-quantize not found at $QUANTIZE_BIN (the image must build llama.cpp)."

    local imatrix_args=()
    if [[ "${USE_IMATRIX:-0}" == "1" ]]; then
        [ -f "${IMATRIX_PATH:-}" ] || die "USE_IMATRIX=1 but importance matrix '${IMATRIX_PATH:-}' is missing."
        imatrix_args=(--imatrix "$IMATRIX_PATH")
    elif [[ "$GGUF_NEEDS_IMATRIX" == *" $q "* ]]; then
        die "$q needs an importance matrix; enable IMatrix calibration for this build."
    elif [[ "$GGUF_WANTS_IMATRIX" == *" $q "* ]]; then
        echo "WARNING: $q without an importance matrix loses quality; enable IMatrix calibration for better results." >&2
    fi

    f16_file="$SCRATCH_DIR/tmp-${MODEL_NAME}-F16.gguf"
    out_file="$OUTPUT_DIR/${MODEL_NAME}-${q}.gguf"
    convert_to_gguf f16 "$f16_file"
    echo ">> Quantizing -> $q"
    "$QUANTIZE_BIN" "${imatrix_args[@]}" "$f16_file" "$out_file" "$q"
    rm -f "$f16_file"
}

build_imatrix() {
    local dataset="${DATASET_PATH:-}" f16_file
    [ -f "$dataset" ] || die "Calibration dataset not found at '$dataset'."
    [ -x "$IMATRIX_BIN" ] || die "llama-imatrix not found at $IMATRIX_BIN (the image must build llama.cpp)."
    mkdir -p "$IMATRIX_DIR"
    f16_file="$SCRATCH_DIR/tmp-${MODEL_NAME}-F16.gguf"
    convert_to_gguf f16 "$f16_file"
    echo ">> Computing importance matrix..."
    # -o *.dat keeps the legacy format, which llama-quantize --imatrix accepts.
    "$IMATRIX_BIN" -m "$f16_file" -f "$dataset" -o "$IMATRIX_DIR/imatrix.dat" --chunks "${IMATRIX_CHUNKS:-100}"
    rm -f "$f16_file"
}

# --- Dispatch ----------------------------------------------------------------

echo "=== Build Started: [MODULE_NAME] ==="
echo "Model:        $MODEL_SOURCE"
echo "Task:         ${MODEL_TASK:-LLM}"
echo "Format:       $FORMAT"
echo "Board:        ${BOARD:-<default>}"
echo "Quantization: $QUANT_TYPE"
echo "Job:          $JOB_TYPE"

[ -n "$MODEL_SOURCE" ] && [ -e "$MODEL_SOURCE" ] || die "MODEL_SOURCE '$MODEL_SOURCE' does not exist in the container."

if [[ "$JOB_TYPE" == "imatrix" ]]; then
    build_imatrix
    echo "Done (imatrix)."
    exit 0
fi

case "$FORMAT" in
    gguf) ;;
    *) die "Format '$FORMAT' is not supported by this target (gguf)." ;;
esac

mkdir -p "$OUTPUT_DIR"

# --- SDK SETUP ---
# [SDK_SETUP_COMMANDS]

# --- CONVERSION & QUANTIZATION ---
case "$QUANT_TYPE" in
[QUANTIZATION_LOGIC]

    *)
        build_gguf "$QUANT_TYPE"
        ;;
esac

# --- PACKAGING ---
# [PACKAGING_COMMANDS]

# A branch that wrote nothing is a failed build, not an empty success.
[ -n "$(ls -A "$OUTPUT_DIR")" ] || die "No artifact in $OUTPUT_DIR for quantization '$QUANT_TYPE'."

cat > "$OUTPUT_DIR/build_info.json" <<EOF
{"model": "$MODEL_NAME", "format": "$FORMAT", "board": "${BOARD:-default}", "quantization": "$QUANT_TYPE", "llama_cpp": "$(cat "$LLAMA_BASE/.llama_cpp_tag" 2>/dev/null || echo unknown)"}
EOF

echo "=== Artifacts ==="
ls -la "$OUTPUT_DIR"
echo "Done."
